application.css:
* {
  box-sizing: border-box;
}

:root {
  color-scheme: light;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #172033;
  background: #eef2f7;
}

body {
  margin: 0;
  min-width: 320px;
  background: linear-gradient(145deg, #eef2f7 0%, #dfe8f2 100%);
}

.app-shell {
  width: min(100% - 2rem, 760px);
  margin: 0 auto;
  padding: 3rem 0 4rem;
}

.app-header {
  margin-bottom: 2rem;
}

.eyebrow {
  margin: 0 0 .5rem;
  color: #315d8f;
  font-size: .8rem;
  font-weight: 800;
  letter-spacing: .12em;
  text-transform: uppercase;
}

h1, h2, p {
  margin-top: 0;
}

h1 {
  margin-bottom: .5rem;
  color: #101a2c;
  font-size: clamp(2rem, 6vw, 3.25rem);
  line-height: 1.1;
}

h2 {
  margin-bottom: 1rem;
  font-size: 1.25rem;
}

.intro {
  max-width:  fiftyrem;
  margin-bottom: 0;
  color: #4c5b70;
}

.todo-panel,
.tasks-section {
  padding: clamp(1.25rem, 4vw, 2rem);
  border: 1px solid #d3dce8;
  border-radius: 14px;
  background: #fff;
  box-shadow: 0 8px 24px rgba(24, 43, 68, .08);
}

.todo-panel {
  margin-bottom: 1.5rem;
}

.input-row {
  display: flex;
  align-items: end;
  gap: .75rem;
}

.field-group {
  flex: 1 1 auto;
}

label {
  display: block;
  margin-bottom: .4rem;
  color: #26364c;
  font-size: .9rem;
  font-weight: 700;
}

input {
  width: 100%;
  min-height: 2.75rem;
  padding: .65rem .75rem;
  border: 1px solid #8798ad;
  border-radius: 7px;
  color: #172033;
  background: #fff;
  font: inherit;
}

button {
  min-height: 2.75rem;
  padding: .6rem 1rem;
  border: 1px solid transparent;
  border-radius: 7px;
  color: #fff;
  background: #245b91;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
}

button:hover {
  background: #1b4875;
}

button:focus-visible,
input:focus-visible {
  outline: 3px solid #f0a528;
  outline-offset: 2px;
}

.form-message {
  margin: .6rem 0 0;
  color: #a32929;
  font-size: .9rem;
  font-weight: 600;
}

.tasks-heading-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
}

.tasks-heading-row h2 {
  margin-bottom: 0;
}

.count {
  margin-bottom: 0;
  color: #315d8f;
  font-size: .95rem;
  font-weight: 700;
}

.task-list {
  display: grid;
  gap: .7rem;
  margin: 1.25rem 0 0;
  padding: 0;
  list-style: none;
}

.task-item {
  display: flex;
  align-items: center;
  gap: .75rem;
  padding: .85rem 1rem;
  border: 1px solid #d3dce8;
  border-radius: 8px;
  background: #f8fafc;
}

.task-text {
  flex: 1;
  overflow-wrap: anywhere;
}

.task-item.completed .task-text {
  color: #627083;
  text-decoration: line-through;
}

.complete-button {
  flex: 0 0 auto;
  width: 1.35rem;
  min-height: 1.35rem;
  padding: 0;
  border: 2px solid #52708f;
  border-radius: 50%;
  background: #fff;
  font-size: 0;
}

.task-item.completed .complete-button {
  border-color: #237044;
  background: #237044;
}

.delete-button {
  min-height: 2.1rem;
  padding: .35rem .65rem;
  color: #9a2828;
  border-color: #d8a3a3;
  background: #fff;
  font-size: .9rem;
}

.delete-button:hover {
  color: #fff;
  background: #9a2828;
}

.empty-message {
  margin: 1.25rem 0 0;
  color: #59697d;
}

@media (max-width: 520px) {
  .app-shell {
    padding-top: 2rem;
  }

  .input-row {
    align-items: stretch;
    flex-direction: column;
  }

  .input-row button {
    width: 100%;
  }

  .task-item {
    align-items: flex-start;
  }
}

