const taskForm = document.querySelector('#task-form');
const taskInput = document.querySelector('[data-testid="task-input"]');
const taskList = document.querySelector('[data-testid="task-list"]');
const incompleteCount = document.querySelector('[data-testid="incomplete-count"]');
const countLabel = document.querySelector('#count-label');
const emptyMessage = document.querySelector('#empty-message');
const taskError = document.querySelector('#task-error');

let tasks = [];
let nextTaskId = 1;

function showError(message) {
  taskError.textContent = message;
  taskError.hidden = false;
}

function clearError() {
  taskError.textContent = '';
  taskError.hidden = true;
}

function createTask(text) {
  return { id: nextTaskId++, text, completed: false };
}

function createTaskElement(task) {
  const item = document.createElement('li');
  item.className = 'task-item';
  item.dataset.testid = 'task';
  item.dataset.completed = String(task.completed);
  if (task.completed) item.classList.add('completed');

  const completeButton = document.createElement('button');
  completeButton.type = 'button';
  completeButton.className = 'complete-button';
  completeButton.dataset.testid = 'task-complete';
  completeButton.setAttribute('aria-label', task.completed ? `Mark ${task.text} as incomplete` : `Mark ${task.text} as complete`);
  completeButton.setAttribute('aria-pressed', String(task.completed));
  completeButton.addEventListener('click', () => toggleTask(task.id));

  const text = document.createElement('span');
  text.className = 'task-text';
  text.dataset.testid = 'task-text';
  text.textContent = task.text;

  const deleteButton = document.createElement('button');
  deleteButton.type = 'button';
  deleteButton.className = 'delete-button';
  deleteButton.dataset.testid = 'task-delete';
  deleteButton.textContent = 'Delete';
  deleteButton.setAttribute('aria-label', `Delete ${task.text}`);
  deleteButton.addEventListener('click', () => deleteTask(task.id));

  item.append(completeButton, text, deleteButton);
  return item;
}

function updateCount() {
  const incomplete = tasks.filter(task => !task.completed).length;
  incompleteCount.textContent = String(incomplete);
  countLabel.textContent = incomplete === 1 ? 'incomplete' : 'incomplete';
}

function renderTasks() {
  taskList.replaceChildren(...tasks.map(createTaskElement));
  emptyMessage.hidden = tasks.length > 0;
  updateCount();
}

function addTask() {
  const text = taskInput.value.trim();
  if (!text) {
    showError('Enter a task before adding it.');
    taskInput.focus();
    return;
  }
  clearError();
  tasks.push(createTask(text));
  taskInput.value = '';
  renderTasks();
  taskInput.focus();
}

function toggleTask(id) {
  const task = tasks.find(item => item.id === id);
  if (!task) return;
  task.completed = !task.completed;
  renderTasks();
}

function deleteTask(id) {
  tasks = tasks.filter(task => task.id !== id);
  renderTasks();
}

taskForm.addEventListener('submit', event => {
  event.preventDefault();
  addTask();
});

renderTasks();
